BEGIN;

CREATE TABLE IF NOT EXISTS public.problem_catalog (
    problem_type TEXT NOT NULL CHECK (problem_type IN ('CODING', 'SQL')),
    problem_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    title TEXT NOT NULL,
    topic TEXT NOT NULL,
    difficulty TEXT NOT NULL CHECK (difficulty IN ('Easy', 'Medium', 'Hard')),
    description TEXT NOT NULL,
    examples JSONB NOT NULL DEFAULT '[]'::JSONB,
    problem_constraints JSONB NOT NULL DEFAULT '[]'::JSONB,
    expected_output TEXT,
    public_test_cases JSONB NOT NULL DEFAULT '[]'::JSONB,
    starter_code JSONB NOT NULL DEFAULT '{}'::JSONB,
    schema_data JSONB NOT NULL DEFAULT '[]'::JSONB,
    expected_result JSONB NOT NULL DEFAULT '{}'::JSONB,
    source_name TEXT NOT NULL DEFAULT 'LogicFirst',
    source_url TEXT,
    is_published BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (problem_type, problem_id)
);

CREATE INDEX IF NOT EXISTS idx_problem_catalog_published_order
    ON public.problem_catalog (problem_type, is_published, sort_order, problem_id);

CREATE TABLE IF NOT EXISTS public.problem_test_cases (
    problem_type TEXT NOT NULL,
    problem_id BIGINT NOT NULL,
    test_index INTEGER NOT NULL,
    input TEXT NOT NULL,
    expected_output TEXT NOT NULL,
    is_hidden BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (problem_type, problem_id, test_index),
    FOREIGN KEY (problem_type, problem_id)
        REFERENCES public.problem_catalog (problem_type, problem_id)
);

ALTER TABLE public.problem_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.problem_test_cases ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_policies
        WHERE schemaname = 'public'
          AND tablename = 'problem_catalog'
          AND policyname = 'problem_catalog_select_published'
    ) THEN
        CREATE POLICY problem_catalog_select_published
            ON public.problem_catalog
            FOR SELECT
            TO anon, authenticated
            USING (is_published);
    END IF;
END
$$;

REVOKE ALL ON TABLE public.problem_catalog FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.problem_catalog TO anon, authenticated;

REVOKE ALL ON TABLE public.problem_test_cases FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.problem_test_cases TO service_role;

