INSERT INTO public.problem_catalog (
    problem_type, problem_id, title, topic, difficulty, description,
    examples, problem_constraints, expected_output, public_test_cases,
    starter_code, source_name, is_published, sort_order
)
SELECT
    'CODING', problem_id, title, topic, difficulty, description,
    jsonb_build_array(jsonb_build_object('input', example_input, 'output', example_output)),
    jsonb_build_array(problem_constraint),
    example_output,
    jsonb_build_array(jsonb_build_object('name', 'Sample Test 1', 'input', example_input, 'output', example_output)),
    '{"java":"","python":"","c":"","cpp":""}'::JSONB,
    'LogicFirst', TRUE, problem_id
FROM added_coding_problems
ON CONFLICT (problem_type, problem_id) DO NOTHING;

