SELECT setval(
    pg_get_serial_sequence('public.problem_catalog', 'problem_id'),
    (SELECT GREATEST(COALESCE(MAX(problem_id), 1), 1) FROM public.problem_catalog),
    TRUE
);

COMMENT ON TABLE public.problem_catalog IS 'Public coding and SQL problem catalog. Hidden evaluation cases are stored separately.';
COMMENT ON TABLE public.problem_test_cases IS 'Private judge test cases; never readable by anon or authenticated clients.';

COMMIT;
